## Patch sketch

```js
const crypto = require('crypto');

const TOLERANCE_SEC = 300; // 5 minutes

function verify(sigHeader, body, secret) {
  // --- 1. Parse header ---------------------------------------------------
  if (typeof sigHeader !== 'string') {
    throw new Error('webhook: signature header must be a string');
  }

  const parts = {};
  for (const element of sigHeader.split(',')) {
    const idx = element.indexOf('=');
    if (idx === -1) throw new Error('webhook: malformed signature element');
    const key = element.slice(0, idx);
    const val = element.slice(idx + 1);
    parts[key] = val;
  }

  const timestamp = parts['t'];
  const sigHex    = parts['v1'];

  if (!timestamp || !sigHex) {
    throw new Error('webhook: missing t= or v1= in signature header');
  }

  // --- 2. Validate timestamp (anti-replay) --------------------------------
  const ts = Number(timestamp);
  if (!Number.isFinite(ts)) {
    throw new Error('webhook: t= is not a valid number');
  }

  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - ts) > TOLERANCE_SEC) {
    throw new Error('webhook: timestamp outside tolerance window');
  }

  // --- 3. Validate hex format before Buffer conversion --------------------
  if (!/^[0-9a-f]{64}$/i.test(sigHex)) {
    throw new Error('webhook: v1= is not valid sha256 hex');
  }

  // --- 4. Compute expected HMAC over "timestamp.body" ---------------------
  //     Including the timestamp in the signed payload binds the sig to the ts,
  //     preventing an attacker from swapping timestamps on a captured sig.
  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${body}`)
    .digest();

  const sigBuf = Buffer.from(sigHex, 'hex');

  // --- 5. Constant-time comparison ----------------------------------------
  if (expected.length !== sigBuf.length) {
    return false; // lengths are fixed at 32; this is a safeguard
  }

  return crypto.timingSafeEqual(expected, sigBuf);
}

module.exports = { verify };
```

Key changes:

- **Header parsing** — expects `t=<unix>,v1=<hex>`; throws on anything else.
- **Replay protection** — rejects if `|now − t| > 300 s`.
- **Signed payload includes timestamp** — HMAC is computed over `"<timestamp>.<body>"` so the signature is bound to the exact timestamp; an attacker cannot graft a fresh `t=` onto an old signature.
- **Constant-time compare** — uses `crypto.timingSafeEqual` on fixed-length Buffers.
- **Malformed hex** — regex gate rejects non-hex or wrong-length strings before `Buffer.from`.

