PATCH SKETCH

```javascript
const crypto = require('crypto');
const TOLERANCE_MS = 5 * 60 * 1000; // 5 minutes

function verify(sigHeader, body, secret) {
  // 1. Parse "t=<unix>,v1=<hex>"
  if (typeof sigHeader !== 'string') return false;
  const map = {};
  for (const part of sigHeader.split(',')) {
    const eq = part.indexOf('=');
    if (eq < 1) return false;
    map[part.slice(0, eq)] = part.slice(eq + 1);
  }
  const { t: tStr, v1 } = map;
  if (!tStr || !v1) return false;

  // 2. Reject stale/future timestamps before any crypto work
  const t = Number(tStr);
  if (!Number.isInteger(t) || t <= 0) return false;
  if (Math.abs(Date.now() - t * 1000) > TOLERANCE_MS) return false;

  // 3. Validate hex strictly before calling Buffer.from to avoid
  //    silent truncation or a thrown RangeError in timingSafeEqual
  if (!/^[0-9a-f]{64}$/.test(v1)) return false;

  // 4. Bind timestamp to body so a valid (t, sig) pair cannot be
  //    replayed against a different body even within the window
  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${t}.${body}`)
    .digest(); // raw 32-byte Buffer

  // 5. Constant-time compare; both are exactly 32 bytes here
  return crypto.timingSafeEqual(expected, Buffer.from(v1, 'hex'));
}
```

Key changes versus old code:
- Signed payload is `"${t}.${body}"`, binding the timestamp to the body.
- Timestamp staleness check exits before crypto when replay is detected.
- Hex regex guard prevents `timingSafeEqual` from receiving wrong-length Buffers (it throws on mismatch, which leaks info and can crash).
- `timingSafeEqual` replaces `===` to eliminate early-exit timing side-channel.

